head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.vScrenID = "ULDSTF30640.xml";
scwin.gAllChk = false;
scwin.gAhthRnd = "";
scwin.gIsFirstSch = true;
scwin.gLastJob = "";


//팝업창으로 넘길 데이터
scwin.p_isur_cd = "";
scwin.p_chrg_nm = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    //1. 인증년도 초기화
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    yyyy = yyyy + 1; // 2007년부터 D+1년도까지 조회
    var str = "^전체";
    for (var i = yyyy; i >= 2007; i--) {
        str += "," + i + "^" + i;
    }
    cmb_YYYY.CBData = str;
};
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_Grid);
    scwin.gAhthRnd = $c.stf.getObjectValue(cmb_ahth_rnd);
    var url = "/ListedCompany.do?method=listDisclsProfsAhth";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    url += "&YYYY=" + $c.stf.getObjectValue(cmb_YYYY);
    url += "&AHTH_RND=" + scwin.gAhthRnd;
    url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO);
    url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD);
    url += "&LST_HIST_YN=" + $c.stf.getObjectValue(chb_Last);
    url += "&AHTH_YN=" + $c.stf.getObjectValue(cmb_AHTH_YN);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
};


//입력 팝업창 띄우기
scwin.fn_input = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF30641", "/issueinfo/ULDSTF30641.gfm", "공시전문인관리 엑셀업로드", 300, 200, 860, 800, "window");
};



//입력 또는 수정 팝업창 띄우기
scwin.fn_readDisclsEdu = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF30642", "/issueinfo/ULDSTF30642.gfm", "공시전문인 교육이수현황", 200, 200, 940, 420, "window");
};
scwin.fn_Save = function() {
    scwin.gLastJob = "저장";
    var gCnt = 0;
    var flagA = false;
    var flagB = false;
    var flagC = false;
    for (var k = 1; k <= dts_MASTER.getTotalRow(); k++) {
        gStat = dts_MASTER.getRowStatus(k);
        if (gStat == TB_JOB_UPDATE) {
            gCnt++;
            var val1 = dts_MASTER.getCellData(k, "SUPLMNT_EDU_COMPLT_TP_CD"); // 보수교육 이수여부
            var val2 = dts_MASTER.getCellData(k, "DISCLS_PROFS_AHTH_PERSIS_YN"); // 인증유지 여부
            var val3 = dts_MASTER.getCellData(k, "REMK"); // 인증유지여부결정일

            if (val1 == '') {
                flagA = true;
            }
            if (val2 == '') {
                flagB = true;
            }
            if (val3 == '') {
                flagC = true;
            }
        }
    }
    dts_MASTER.setBroadcast(true);
    if (gCnt == 0) {
        $c.win.alert("저장할 내용이 없습니다.");
        return;
    }
    if (flagA && flagB && flagC) {
        $c.win.alert("수정하실 항목의 값을 입력하시기 바랍니다.");
        return;
    }
    if (window.confirm("[총" + gCnt + "건] 저장하겠습니까?")) {
        var url = "/ListedCompany.do?method=procModifyDisclsProfsAhth&TRANSTR_EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_save.Post();
    }
};




// 연관화면 반영 버튼 클릭 시
scwin.fn_Update = function() {
    scwin.gLastJob = "연관화면반영";
    var gCnt = 0;
    var flagA = false;
    for (var k = 1; k <= dts_MASTER.getTotalRow(); k++) {
        gStat = dts_MASTER.getCellData(k, "CHECK");
        if (gStat == "T") {
            gCnt++;
            var val1 = dts_MASTER.getCellData(k, "DISCLS_PROFS_YN"); // 인증여부
            if (val1 == '') {
                flagA = true;
            }
        }
    }
    dts_MASTER.setBroadcast(true);
    if (gCnt == 0) {
        $c.win.alert("반영 대상이 체크되지 않았습니다.");
        return;
    }
    if (flagA) {
        $c.win.alert("[인증여부] 값이 입력되지 않은 데이터가 선택되었습니다.");
        return;
    }
    if (window.confirm("[총" + gCnt + "건]의 인증여부 및 인증시기 값을 연관화면에 반영하시겠습니까?\n현 공시담당자의 경우에만 갱신됩니다.")) {
        var url = "/ListedCompany.do?method=procUpdateFinal&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_save.Post();
    }
};




// 삭제 버튼 클릭 시
scwin.fn_Del = function() {
    scwin.gLastJob = "삭제";
    var gCnt = 0;
    //var seq;

    for (var k = 1; k <= dts_MASTER.getTotalRow(); k++) {
        gStat = dts_MASTER.getCellData(k, "CHECK");
        if (gStat == "T") {
            gCnt++;
            //seq = dts_MASTER.NameValue(k, "SEQ");	// PK		

        }
    }
    dts_MASTER.setBroadcast(true);
    if (gCnt == 0) {
        $c.win.alert("삭제 대상이 체크되지 않았습니다.");
        return;
    }
    if (window.confirm("[총" + gCnt + "건]의 데이터를 삭제하시겠습니까?")) {
        var url = "/ListedCompany.do?method=procDeleteDisclsProfsAhth&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_save.Post();
    }
};
scwin.fn_SelectAll = function() {
    grd_Grid.Redraw = false;
    if (scwin.gAllChk == false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        for (var i = 0; i < dts_MASTER.getTotalRow(); i++) {
            dts_MASTER.setCellData(i + 1, "CHECK", "T");
        }
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        for (var i = 0; i < dts_MASTER.getTotalRow(); i++) {
            dts_MASTER.setCellData(i + 1, "CHECK", "F");
        }
    }
    grd_Grid.Redraw = true;
};


//개별 입력창 팝업 띄우기 
scwin.fn_Insert = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF30643", "/issueinfo/ULDSTF30643.gfm", "공시전문인관리 개별입력", 50, 20, 860, 550, "window");
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_MASTER_OnFail = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadError = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_MASTER.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리


    //2.인증회차 콤보박스 초기화(첫번째 조회에서만 초기화 하도록 한다.)
    if (scwin.gIsFirstSch) {
        var str = "^전체";
        var max = dts_MASTER.getCellData(rowcount, "MAX_RND");
        for (var i = max; i >= 1; i--) {
            str += "," + i + "^" + i;
        }
        cmb_ahth_rnd.CBData = str;
        var tmpIndex = cmb_ahth_rnd.IndexOfColumn("value", scwin.gAhthRnd);
        cmb_ahth_rnd.setSelectedIndex(tmpIndex); // 검색조건의 값으로 index 셋팅

        scwin.gIsFirstSch = false;
    }



    // 저장 에러 발생 시
    function alert_error2(dtsObj) {
        var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
        for (var i = 0; i < USER_DEFINE.length; i++) {
            var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
            var j;
            for (j = 0; j < errorCount; j++) {
                if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                    //'0' 임의로 떨군 INFO 메시지
                    $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
                } else {
                    //기존 에러 메시지
                    $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
                }
            }
        }
    };
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (colid == 'NM') {
        scwin.p_isur_cd = dts_MASTER.getCellData(row, "ISUR_CD"); // 회사코드
        scwin.p_chrg_nm = dts_MASTER.getCellData(row, "NM"); // 담당자명

        scwin.fn_readDisclsEdu();
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD); //;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "공시전문인관리현황", "", "8");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Init();
    scwin.fn_Search();
};
scwin.trs_save_OnSuccess = function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    scwin.fn_Search();
};
scwin.btn_Input_onclick = function() {
    scwin.fn_input();
};
scwin.trs_Save_OnFail = function() {
    alert_error2(trs_Save);
};
scwin.btn_Modify_onclick = function() {
    scwin.fn_Save();
};
scwin.grd_Grid_OnHeadCheckClick = function(col, colid, bCheck) {
    scwin.fn_SelectAll();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Del();
};
scwin.btn_Snd_onclick = function() {
    scwin.fn_Update();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Insert();
};
